  `email_addr` varchar(64) DEFAULT NULL,
  `update_time` varchar(20) NOT NULL,
  `custom_city` varchar(32) DEFAULT NULL,
  `custom_addr` varchar(256) DEFAULT NULL,
  `custom_desc` varchar(512) DEFAULT NULL,
  `custom_desc1` varchar(32) DEFAULT NULL,
  `custom_level` smallint(6) NOT NULL DEFAULT '0',
  `custom_mobile` varchar(20) DEFAULT NULL,
  `custom_phone` varchar(20) DEFAULT NULL,
  `custom_phone2` varchar(20) DEFAULT NULL,
  `is_delete` smallint(6) NOT NULL DEFAULT '0',
  `cust_type` varchar(1024) DEFAULT '0',
  `agentid` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`custom_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
